package com.exito.chop;
import android.content.*;import android.graphics.Typeface;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
final class MiniSamplerView extends ScrollView {
 final Engine e;final LinearLayout root;final TextView state,meta,toneLabel,tempoLabel,pageLabel;final WaveEditor wave;final SeekBar tone,tempo;final Button connect,drums,markNext,voiceMode,videoMode;final Button[] pads=new Button[16];int page;final Runnable listener=this::refresh;
 int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}MiniSamplerView(Context c){super(c);e=Engine.get(c);setBackgroundColor(SamplerView.BG);root=new LinearLayout(c);root.setOrientation(1);root.setPadding(dp(7),dp(3),dp(7),dp(4));addView(root);state=text("",10,SamplerView.LIME,20);ChopVideoView image=new ChopVideoView(c);root.addView(image,new LinearLayout.LayoutParams(-1,dp(150)));LinearLayout videoRow=row();put(videoRow,button("VÍDEO GRANDE + PADS",()->MainActivity.showVideo(c,true)));wave=new WaveEditor(c);wave.selected=()->{page=e.selected/16;refresh();};root.addView(wave,new LinearLayout.LayoutParams(-1,dp(46)));put(videoRow,button("SCRATCH ON/OFF",()->e.setScratchMode(!e.scratchMode)));meta=text("",10,0xffd3e0d0,38);meta.setTypeface(Typography.control(c));meta.setBackgroundColor(0xff102a2a);meta.setOnClickListener(v->MainActivity.launch(c,"source-meta",null));LinearLayout t=row();toneLabel=label("Tono",SamplerView.PINK);t.addView(toneLabel,new LinearLayout.LayoutParams(dp(100),-1));tone=slider(24,12,v->e.setPitch(v-12));t.addView(tone,new LinearLayout.LayoutParams(0,-1,1));LinearLayout b=row();tempoLabel=label("Tempo",SamplerView.BLUE);b.addView(tempoLabel,new LinearLayout.LayoutParams(dp(100),-1));tempo=slider(150,50,v->e.setTempo((v+50)/100f));b.addView(tempo,new LinearLayout.LayoutParams(0,-1,1));LinearLayout nav=row();put(nav,button("◀",()->{page=Math.max(0,page-1);refresh();}));pageLabel=label("",SamplerView.LIME);nav.addView(pageLabel,new LinearLayout.LayoutParams(0,-1,2));put(nav,button("▶",()->{page=Math.min(3,page+1);refresh();}));for(int r=0;r<4;r++){LinearLayout line=row();line.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(52)));line.setMotionEventSplittingEnabled(true);for(int k=0;k<4;k++){final int i=r*4+k;pads[i]=new PadButton(c);pads[i].setOnTouchListener(new PadTouch(e,()->page*16+i));put(line,pads[i]);}}
 LinearLayout actions=row();connect=button("Conectar",()->MainActivity.launch(c,"capture",null));put(actions,connect);markNext=button("CORTAR",e::mark);put(actions,markNext);drums=button("Drums",e.drums::toggle);put(actions,drums);put(actions,button("PARAR",()->{e.harmony.stop();e.sequencer.stop();e.drums.stop();e.stop();}));LinearLayout voices=row();voiceMode=button("",e.slots::toggleMono);put(voices,voiceMode);videoMode=button("",()->{if(e.livePadTake!=null){e.message("Termina la toma antes de cambiar vídeo.");return;}e.history.edit("Vídeo",()->e.captureVideo=!e.captureVideo);});put(voices,videoMode);LinearLayout marks=row();put(marks,button("Nueva toma pads",e::startPadMarking));put(marks,button("Terminar pads",()->e.finishPadMarking(true)));LinearLayout listen=row();put(listen,button("Escuchar cambios",e::listenChanges));LinearLayout edit=row();put(edit,button("↶",()->e.history.move(false)));put(edit,button("↷",()->e.history.move(true)));put(edit,button("Gate",()->e.history.edit("Gate",()->e.gate=!e.gate)));put(edit,button("Zoom",()->wave.selected()));refresh();}
 TextView label(String s,int color){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(10);t.setTextColor(color);t.setTypeface(Typography.body(getContext()));t.setGravity(Gravity.CENTER_VERTICAL);return t;}TextView text(String s,int size,int color,int height){TextView t=label(s,color);t.setTextSize(size);root.addView(t,new LinearLayout.LayoutParams(-1,dp(height)));return t;}
 LinearLayout row(){LinearLayout r=new LinearLayout(getContext());r.setOrientation(0);root.addView(r,new LinearLayout.LayoutParams(-1,dp(36)));return r;}void put(LinearLayout row,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(1),dp(1),dp(1),dp(1));row.addView(v,p);}Button button(String s,Runnable r){Button b=new Button(getContext());b.setText(s);b.setTextSize(10);b.setTypeface(Typography.control(getContext()));b.setMaxLines(2);b.setAutoSizeTextTypeUniformWithConfiguration(8,10,1,android.util.TypedValue.COMPLEX_UNIT_SP);b.setTextColor(SamplerView.FG);b.setAllCaps(false);b.setPadding(0,0,0,0);b.setMinWidth(0);b.setMinimumWidth(0);GradientDrawable d=new GradientDrawable();d.setColor(SamplerView.PANEL);d.setStroke(dp(1),SamplerView.BLUE);d.setCornerRadius(dp(4));b.setBackground(d);b.setOnClickListener(v->r.run());return b;}
 SeekBar slider(int max,int initial,java.util.function.IntConsumer action){SeekBar s=new SeekBar(getContext());s.setMax(max);s.setProgress(initial);s.setProgressTintList(android.content.res.ColorStateList.valueOf(SamplerView.LIME));s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){e.history.begin("Tono y tempo");}public void onProgressChanged(SeekBar s,int p,boolean user){if(user&&!e.busy){action.accept(p);e.changed();}}public void onStopTrackingTouch(SeekBar s){e.prepare();if(!e.busy)e.history.end();}});return s;}
 void refresh(){state.setText(e.livePadTake!=null?"DIRECTO · "+e.padCount()+"/64 · "+String.format(java.util.Locale.US,"%.1f s",e.livePadTake.frames()/(double)e.livePadTake.rate):e.padMarking?"MARCANDO · "+e.padCount()+"/64 · "+e.padActionLabel():e.liveMode?e.liveStatus:e.name+(e.busy?" · procesando":""));if(e.padMarking)page=Math.min(3,e.padCount()/16);Slots.Slot s=e.slots.list[e.slots.active];int key=Math.floorMod(s.key%12+Math.round(e.semitones),12)+s.key/12*12;meta.setText(e.metadataText());toneLabel.setText(String.format(java.util.Locale.US,"Tono %+.0f st",e.semitones));tempoLabel.setText("Tempo "+Math.round(e.tempo*100)+" %");if(!tone.isPressed())tone.setProgress(Math.round(e.semitones)+12);if(!tempo.isPressed())tempo.setProgress(Math.round(e.tempo*100)-50);pageLabel.setText("PADS "+(page*16+1)+"–"+(page*16+16)+(e.gate?" · GATE":" · ONE SHOT"));for(int i=0;i<16;i++){int n=page*16+i;pads[i].setText(String.format(java.util.Locale.US,"%02d\n",n+1)+((e.padMarking||PadChops.EMPTY.equals(e.chopMode))&&n==e.padCount()?" "+e.padActionLabel():e.hasPad(n)?" ●":" —"));pads[i].setEnabled(e.canTapPad(n));pads[i].setSelected(e.selected==n&&e.hasPad(n));pads[i].setActivated(!e.hasPad(n)&&e.canTapPad(n));}voiceMode.setText(e.slots.list[e.slots.active].mono?"VOZ MONO":"VOZ POLI");videoMode.setText(e.captureVideo?"Vídeo ON":"Vídeo OFF");markNext.setText(e.padMarking?e.padActionLabel()+" "+(e.padCount()+1):"CORTAR");connect.setText(e.capturing?"Desconectar":"Conectar");drums.setText(e.drums.playing?"Drums OFF":"Drums ON");wave.invalidate();}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();e.listeners.add(listener);refresh();}@Override protected void onDetachedFromWindow(){e.listeners.remove(listener);super.onDetachedFromWindow();}
}
